# Read-only exact candidate evidence assessment.
.vs_hashes<-function(value,name,empty=FALSE){value<-.ex_object(value,name);if(!length(value)&&!empty).cr_error('RELEASE_HASHES',paste(name,'cannot be empty'));for(key in names(value)){.vb_string(key,paste(name,'key'));digest<-value[[key]];if(!is.character(digest)||length(digest)!=1||is.na(digest)||!grepl('^[0-9a-f]{64}$',digest)).cr_error('RELEASE_HASHES',paste(name,'requires lowercase SHA-256 values'))};value}
release_candidate_assessment<-function(candidate,evidence,requirements,context=NULL){
 cnd<-.ex_object(candidate,'candidate');candidate_id<-.vb_string(cnd$candidate_id,'candidate_id');artifacts<-.vs_hashes(cnd$artifact_hashes,'artifact_hashes');resources<-.vs_hashes(cnd$resource_hashes,'resource_hashes',empty=TRUE);runtimes<-c('python_wheel','python_sdist','native_r');if(!all(runtimes%in%names(artifacts))).cr_error('RELEASE_ARTIFACTS','Candidate must identify wheel, sdist and native R artifacts');req<-.ex_object(requirements,'requirements');for(key in c('requirements_id','version','reference')).vb_string(req[[key]],key);map<-c(CELL='required_cell_ids',JOURNEY='required_journey_ids',GENERATOR='required_generator_ids',PROFILE='required_profile_ids');scopes<-setNames(lapply(names(map),function(kind).ex_ids(req[[map[[kind]]]],map[[kind]],empty=kind%in%c('GENERATOR','PROFILE'))),names(map));expected_resources<-.vs_hashes(req$resource_hashes,'required resource_hashes',empty=TRUE);limits<-.ex_object(req$limits,'limits');max_seconds<-.vb_number(limits$max_runtime_seconds,'max_runtime_seconds',0);max_mb<-.vb_number(limits$max_peak_memory_mb,'max_peak_memory_mb',0);if(max_seconds==0||max_mb==0).cr_error('RELEASE_BUDGET','Strictly positive predeclared execution budgets required');rows<-.vs_index(evidence,'evidence_id','evidence')$rows;violations<-gates<-list();issue<-function(code,unit,detail)violations[[length(violations)+1]]<<-list(code=code,unit_id=unit,detail=detail);equal<-function(a,b)identical(.cr_hash(a),.cr_hash(b));if(!equal(resources,expected_resources))issue('RESOURCE_MANIFEST_MISMATCH',candidate_id,'Candidate resources differ from frozen requirements');eligible<-list()
 for(e in rows){eid<-e$evidence_id;for(key in c('scope_type','scope_id','kind','language','status','reference','data_origin')).vb_string(e[[key]],paste('evidence',key));.vs_hashes(list(content=e$content_hash),'evidence content_hash');if(!e$data_origin%in%c('SYNTHETIC','EMPIRICAL','SOFTWARE','MIXED')).cr_error('RELEASE_ORIGIN','Explicit evidence data origin required');if(!e$scope_type%in%c(names(scopes),'PACKAGE')).cr_error('RELEASE_SCOPE','Unknown evidence scope type');known<-if(e$scope_type=='PACKAGE')e$scope_id%in%runtimes else e$scope_id%in%scopes[[e$scope_type]];if(!known)issue('UNDECLARED_EVIDENCE_SCOPE',eid,'Evidence is outside the frozen release obligations');ea<-.vs_hashes(e$artifact_hashes,'evidence artifact_hashes');er<-.vs_hashes(e$resource_hashes,'evidence resource_hashes',empty=TRUE);if(!identical(e$candidate_id,candidate_id)||!equal(ea,artifacts)||!equal(er,resources)){issue('WRONG_CANDIDATE_EVIDENCE',eid,'Evidence is not bound to this exact artifact/resource manifest');next};eligible[[length(eligible)+1]]<-e}
 obligations<-list();for(cid in scopes$CELL)for(kind in .vs_cell_evidence)for(language in if(kind=='parity')'both'else c('python','r'))obligations[[length(obligations)+1]]<-c('CELL',cid,kind,language);for(kind in c('JOURNEY','GENERATOR','PROFILE'))for(sid in scopes[[kind]])for(runtime in runtimes)obligations[[length(obligations)+1]]<-c(kind,sid,'installed_execution',runtime);for(runtime in runtimes)obligations[[length(obligations)+1]]<-c('PACKAGE',runtime,'installed_execution',runtime)
 for(ob in obligations){scope_type<-ob[1];sid<-ob[2];kind<-ob[3];language<-ob[4];key<-paste(ob,collapse='/');matching<-Filter(function(e)identical(c(e$scope_type,e$scope_id,e$kind,e$language),ob),eligible);before<-length(violations);if(!length(matching))issue('MISSING_REQUIRED_EVIDENCE',key,'No exact-candidate evidence for this mandatory gate');for(e in matching){if(e$status!='PASS')issue('NONPASS_REQUIRED_EVIDENCE',e$evidence_id,'Mandatory failed, skipped or non-applicable evidence cannot pass');if(kind=='installed_execution'){flags<-list(executed=TRUE,installed=TRUE,offline=TRUE,source_tree_access=FALSE);if(any(vapply(names(flags),function(k)!identical(e[[k]],flags[[k]]),logical(1))))issue('INVALID_INSTALLED_EXECUTION',e$evidence_id,'Require executed installed offline run without source-tree access');for(metric in c('runtime_seconds','peak_memory_mb')){limit<-if(metric=='runtime_seconds')max_seconds else max_mb;v<-e[[metric]];if(!is.numeric(v)||length(v)!=1||!is.finite(v)||v<0||v>limit)issue('EXECUTION_BUDGET_UNPROVEN',e$evidence_id,paste0(metric,' missing, nonfinite or exceeds declared budget'))}}};gates[[length(gates)+1]]<-list(gate_id=key,status=if(length(violations)==before)'PASS'else'BLOCKED',evidence_ids=lapply(matching,function(e)e$evidence_id))}
 payload<-list(candidate=cnd,requirements=req,applicability='APPLICABLE',gates=gates,metrics=list(required_gate_count=length(gates),passed_gate_count=sum(vapply(gates,function(g)g$status=='PASS',logical(1)))),assessment_axes=list(software_system=if(length(violations))'BLOCKED'else'PASS',synthetic_method_evidence=if(any(vapply(eligible,function(e)e$data_origin=='SYNTHETIC',logical(1))))'PRESENT'else'NOT_ASSESSED',empirical_model_performance='NOT_ASSESSED',regulatory_approval='NOT_ASSESSED'),publication_performed=FALSE,tests_executed_by_assessor=FALSE,candidate_manifest_hash=.cr_hash(list(candidate_id=candidate_id,artifact_hashes=artifacts,resource_hashes=resources)));.vs_finish('release_candidate_assessment',payload,violations,list(candidate=cnd,evidence=rows,requirements=req),context)
}
